result.output:
        if not self.blocks:
            return None
        first = self.blocks[0]
        return (
            f"Stopped for safety: the site sent the browser to {first['host']}, which is a private, local or "
            f"cloud-metadata address ({', '.join(first['addresses'])}). "
            "First User never visits those, so the visit ended here."
        )

    async def _vet(self, host: str, port: int, url: str) -> Decision:
        key = host.lower()
        if key in self._decisions:
            decision = self._decisions[key]
        else:
            lock = self._locks.setdefault(key, asyncio.Lock())
            async with lock:
                if key not in self._decisions:
                    result = await _check_host(key, port)
                    self._decisions[key] = Decision(
                        result["allowed"], result["addresses"], result["reason"], result["private"]
                    )
            decision = self._decisions[key]
        if decision.private:
            self._refused({"host": host, "port": port, "url": url, "addresses": decision.addresses,
                           "reason": decision.reason})
        return decision

    async def _handle(self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter) -> None:
        task = asyncio.current_task()
        self._connections.add(task)
        upstream: asyncio.StreamWriter | None = None
        try:
            try:
                head = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), HEADER_TIMEOUT_SECONDS)
            except (asyncio.IncompleteReadError, asyncio.LimitOverrunError, asyncio.TimeoutError):
                return
            if len(head) > MAX_HEADER_BYTES:
                return await _reply(writer, 431, "Request Header Fields Too Large")
            request_line, *header_lines = head.decode("latin-1").split("\r\n")
            parts = request_line.split(" ")
            if len(parts) != 3:
                return await _reply(writer, 400, "Bad Request")
            method, target, version = parts

            if method == "CONNECT":
                host, port = _split_host_port(target, default_port=443)
                url = f"https://{target}"
                if port == self.devtools_port and host.lower() in ("127.0.0.1", "localhost"):
                    return await self._devtools_tunnel(reader, writer, host, port)
            else:
                split = urlsplit(target)
                if split.scheme != "http" or not split.hostname:
                    return await _reply(writer, 400, "Bad Request")
                host, port = split.hostname, split.port or 80
                url = target

            decision = await self._vet(host, port, url)
            if decision.private:
                return await _reply(writer, 403, "Forbidden by First User egress guard")
            if not decision.allowed:
                return await _reply(writer, 502, "Bad Gateway")

            upstream_reader, upstream = await _open_vetted(decision.addresses, port)
            if upstream is None:
                return await _reply(writer, 502, "Bad Gateway")

            if method == "CONNECT":
                writer.write(b"HTTP/1.1 200 Connection Established\r\n\r\n")
            else:
                # One request per connection: a reused client connection could name another host.
                path = urlsplit(target)._replace(scheme="", netloc="").geturl() or "/"
                headers = [
                    line for line in header_lines
                    if line and line.split(":", 1)[0].strip().lower()
                    not in ("proxy-connection", "connection", "keep-alive", "proxy-authorization")
                ]
                request = f"{method} {path} {version}\r\n" + "".join(f"{h}\r\n" for h in headers)
                upstream.write((request + "Connection: close\r\n\r\n").encode("latin-1"))
            await writer.drain()
            await asyncio.gather(_pipe(reader, upstream), _pipe(upstream_reader, writer))
        except (ConnectionError, OSError, ValueError):
            pass
        finally:
            self._connections.discard(task)
            for stream in (upstream, writer):
                if stream is not None:
                    stream.close()

    async def _devtools_tunnel(self, reader, writer, host: str, port: int) -> None:
        """Forward a tunnel to Chrome's DevTools port only if its first request comes from an extension.

        Stagehand launches Chrome with --remote-allow-origins=*, so DevTools itself
        would accept a websocket from any page. A DevTools websocket is plain HTTP
        inside the tunnel, and browsers always send an Origin header that pages
        cannot forge, so the guard checks it here instead.
        """
        writer.write(b"HTTP/1.1 200 Connection Established\r\n\r\n")
        await writer.drain()
        try:
            head = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), HEADER_TIMEOUT_SECONDS)
        except (asyncio.IncompleteReadError, asyncio.LimitOverrunError, asyncio.TimeoutError):
            return
        request_line, *header_lines = head.decode("latin-1").split("\r\n")
        origin = next(
            (line.split(":", 1)[1].strip() for line in header_lines if line.lower().startswith("origin:")), ""
        )
        # Only a browser extension (Stagehand's) may use the DevTools port.
        if not origin.startswith("chrome-extension://"):
            self._refused({"host": host, "port": port, "url": f"DevTools: {request_line[:200]}",
                           "addresses": [host], "reason": f"DevTools request from origin {origin or 'none'}"})
            return
        upstream_reader, upstream = await _open_vetted(["127.0.0.1"], port)
        if upstream is None:
            return
        try:
            upstream.write(head)
            await asyncio.gather(_pipe(reader, upstream), _pipe(upstream_reader, writer))
        finally:
            upstream.close()


@neatlogs.span(kind="GUARDRAIL", name="egress_refused")
def _refusal_span(record: dict) -> dict:
    """One span per refused request: synchronous, so it cannot be cut off by cancellation."""
    return {"refused": True, **record}


@neatlogs.span(kind="GUARDRAIL", name="egress_summary")
def summary_span(summary: dict) -> dict:
    """The guard's work for one run: how many hosts were checked, and which were refused."""
    return summary


async def _check_host(host: str, port: int) -> dict:
    """Resolve a host once per run and decide whether the browser may connect to it."""
    try:
        infos = await asyncio.get_running_loop().getaddrinfo(host, port, type=socket.SOCK_STREAM)
    except (socket.gaierror, UnicodeError) as error:
        # Not a safety block: the browser could not have loaded it either.
        return {"allowed": False, "private": False, "host": host, "addresses": [],
                "reason": f"could not resolve: {error}"}
    addresses = list(dict.fromkeys(info[4][0].split("%")[0] for info in infos))
    if not addresses:
        return {"allowed": False, "private": False, "host": host, "addresses": [], "reason": "no addresses"}
    blocked = [a for a in addresses if is_blocked_address(ipaddress.ip_address(a))]
    if blocked:
        # Refuse the whole host if any address is non-public, so it cannot be steered there.
        return {"allowed": False, "private": True, "host": host, "addresses": addresses,
                "reason": f"non-public address: {', '.join(blocked)}"}
    return {"allowed": True, "private": False, "host": host, "addresses": addresses, "reason": ""}


async def _open_vetted(addresses: list[str], port: int):
    for address in addresses:
        try:
            return await asyncio.wait_for(asyncio.open_connection(address, port), CONNECT_TIMEOUT_SECONDS)
        except (OSError, asyncio.TimeoutError):
            continue
    return None, None


async def _pipe(source: asyncio.StreamReader, sink: asyncio.StreamWriter) -> None:
    try:
        while data := await source.read(PIPE_CHUNK):
            sink.write(data)
            await sink.drain()
    except (ConnectionError, OSError):
        pass
    finally:
        if sink.can_write_eof():
            try:
                sink.write_eof()
            except (OSError, RuntimeError):
                pass


async def _reply(writer: asyncio.StreamWriter, status: int, message: str) -> None:
    body = message.encode()
    writer.write(
        f"HTTP/1.1 {status} {message}\r\nContent-Type: text/plain\r\nContent-Length: {len(body)}\r\n"
        "Connection: close\r\n\r\n".encode() + body
    )
    await writer.drain()


def _split_host_port(target: str, default_port: int) -> tuple[str, int]:
    if target.startswith("["):
        host, _, rest = target[1:].partition("]")
        return host, int(rest[1:]) if rest.startswith(":") else default_port
    host, _, port = target.rpartition(":")
    return (host, int(port)) if host else (target, default_port)
"""One first-time visit: open Chrome behind the egress guard, run the visitor agent, close Chrome."""

import neatlogs

import page_watch
import trace_safety
from browse import run_persona
from browser import close_browser, open_browser
from config import PAGE_READY_TIMEOUT_MS
from egress import summary_span
from first_impression import write_review
from tools import RunContext


# capture_input=False: `recorder` is an object (see browse.run_persona); the plain-text inputs
# are recorded explicitly.
@neatlogs.span(kind="WORKFLOW", name="first_visit", capture_input=False)
async def first_visit(
    url: str,
    goal: str,
    run_id: str,
    recorder=None,
    start_url: str | None = None,
    credentials=None,
    test_login_unavailable: bool = False,
    access_mode: str = "signup",
    access_mode_chosen: bool = True,
) -> dict:
    """Everything a visit does, background work included, finishes inside this root span.

    `start_url` is a page past the login the founder gave; the visit begins there. `credentials`
    is their throwaway test login (credentials.TestCredentials); it is only typed into the page
    being tested. `test_login_unavailable` means a login was provided but could not be loaded.
    `access_mode` is how the founder let the visitor in: "public", "link", "account" or "signup".
    """
    # Only plain values are recorded as the span's input: `credentials` and `recorder` are objects.
    trace_safety.set_input(url=url, goal=goal, run_id=run_id, start_url=start_url, access_mode=access_mode,
                           test_login=bool(credentials) or test_login_unavailable)
    if credentials is not None:
        # From here, the values are redacted in every span and scrubbed from every tool result.
        credentials.register()
    trace_id = current_trace_id()
    browser, stagehand, page, guard = await open_browser()
    try:
        await page_watch.install(page)
        ctx = RunContext(
            url=url, goal=goal, run_id=run_id, stagehand=stagehand, page=page, recorder=recorder, egress=guard,
            credentials=credentials, start_url=start_url, access_mode=access_mode,
            access_mode_chosen=access_mode_chosen,
        )
        if credentials is not None:
            ctx.entry["test_login"] = "provided_not_used"
        elif test_login_unavailable:
            ctx.entry["test_login"] = "failed"

        # The first impression is always of the public landing page, what a newcomer sees without
        # logging in, so with a start link the visit goes there afterwards.
        await open_start_page(page, url, guard)
        if not guard.blocks:
            await _first_impression(ctx)
        if start_url:
            await open_start_page(page, start_url, guard)
        result = await run_persona(ctx)
    finally:
        # Closes the browser, the guard's connections and the lookup client before the root ends.
        await close_browser(browser, stagehand, guard)
        egress_summary = summary_span(guard.summary())
    return {**result, "egress": egress_summary, "trace_id": trace_id}


async def _first_impression(ctx: RunContext) -> None:
    """Write the review of the landing page and save it at once, so the live page can show it."""
    await _settle(ctx.page)
    ctx.first_impression_tried = True
    ctx.first_impression = await write_review(ctx.url, ctx.page, ctx.usage)
    if ctx.first_impression is not None and ctx.recorder is not None and hasattr(ctx.recorder, "first_impression"):
        try:
            await ctx.recorder.first_impression(ctx.first_impression)
        except Exception as error:
            print(f"[first impression]   !! could not record it: {type(error).__name__}", flush=True)


async def _settle(page, seconds: float = 6.0) -> None:
    """Give a script-rendered page a moment to put something on screen before it is read."""
    waited = 0.0
    while waited < seconds:
        try:
            text_length = await page.evaluate("document.body ? document.body.innerText.trim().length : 0")
            ready = await page.evaluate("document.readyState")
        except Exception:
            return
        if text_length > 80 and ready != "loading":
            break
        await page.wait_for_timeout(500)
        waited += 0.5
    await page.wait_for_timeout(700)


def current_trace_id() -> str | None:
    """The neatlogs trace id of the active span, from its W3C traceparent header."""
    headers: dict[str, str] = {}
    if not neatlogs.inject_trace_context(headers):
        return None
    parts = headers.get("traceparent", "").split("-")
    return parts[1] if len(parts) == 4 else None


# A page whose own scripts failed to load is reloaded like a person would, this many times at most.
MAX_RELOADS = 2
ASSET_SETTLE_SECONDS = 10


async def open_start_page(page, url: str, guard) -> None:
    """Navigate and continue once the DOM is ready, without waiting for the full load event.

    Slow scripts or third-party resources can hold up even DOMContentLoaded (on
    the-internet.herokuapp.com it takes about 35 s in Chrome). After PAGE_READY_TIMEOUT_MS
    the visit goes ahead with whatever has rendered, unless nothing has. If the page's own
    scripts or stylesheets then turn out to have failed to load, it is reloaded (see below).
    """
    try:
        await page.goto(url, wait_until="domcontentloaded", timeout=PAGE_READY_TIMEOUT_MS)
    except Exception:
        # A refused navigation can surface as a load error; the guard's record says why.
        if guard.blocks:
            return
        if not await _has_rendered(page):
            raise
        print(f"[visit] {url} was not ready after {PAGE_READY_TIMEOUT_MS / 1000:.0f} s; continuing with what "
              "has rendered", flush=True)
    await reload_if_broken(page, guard)


async def reload_if_broken(page, guard) -> list[dict]:
    """Reload a page whose own scripts or stylesheets failed to load, as a person would press reload.

    A site can fail to serve a file for a moment (the-internet.herokuapp.com answers some static files
    with a 503 after 30 s, with or without our proxy). The page then loads without its scripts and
    nothing on it works, which is a flaky load, not a finding. At most MAX_RELOADS reloads. Returns the
    assets that are still failing afterwards (empty when the page is whole), which the visit reports as
    the site's problem if it stays broken. Never touches the egress guard's rules: a reload goes through
    the same proxy and is vetted like any request.
    """
    failed: list[dict] = []
    for attempt in range(MAX_RELOADS + 1):
        await _wait_for_assets(page)
        failed = await page_watch.failed_assets(page)
        if not failed or getattr(guard, "blocks", None) or attempt == MAX_RELOADS:
            break
        print(f"[visit] {len(failed)} of the page's own files failed to load "
              f"({page_watch.describe_assets(failed)}); reloading ({attempt + 1}/{MAX_RELOADS})", flush=True)
        try:
            await page.reload(wait_until="domcontentloaded", timeout=PAGE_READY_TIMEOUT_MS)
        except Exception:
            if getattr(guard, "blocks", None) or not await _has_rendered(page):
                break
    return failed


async def _wait_for_assets(page) -> None:
    """Let a page's remaining scripts and styles finish (or fail), up to ASSET_SETTLE_SECONDS."""
    for _ in range(ASSET_SETTLE_SECONDS * 2):
        try:
            if await page.evaluate("document.readyState") == "complete":
                return
        except Exception:
            return
        await page.wait_for_timeout(500)


async def _has_rendered(page) -> bool:
    try:
        return (await page.url()).startswith(("http://", "https://")) and bool(
            await page.evaluate("document.body ? document.body.innerText.trim().length > 0 : false")
        )
    except Exception:
        return False

def forget_secrets() -> None:
    """Tests only: production keeps registered secrets, see above."""
    _registered.clear()


def _replace_registered(text: str) -> str:
    for value in sorted(_registered, key=len, reverse=True):
        label = _registered[value]
        if "@" in value:
            text = re.sub(re.escape(value), lambda _m, label=label: label, text, flags=re.IGNORECASE)
        elif value in text:
            text = text.replace(value, label)
    return text


def scrub_text(text: str) -> str:
    """Replace registered run-time secrets in a string with their labels."""
    return _replace_registered(text) if _registered and isinstance(text, str) else text


def scrub(value):
    """scrub_text over every string in a nested dict / list; other values are returned as they are."""
    if not _registered:
        return value
    if isinstance(value, str):
        return _replace_registered(value)
    if isinstance(value, dict):
        return {key: scrub(item) for key, item in value.items()}
    if isinstance(value, list):
        return [scrub(item) for item in value]
    if isinstance(value, tuple):
        return tuple(scrub(item) for item in value)
    return value


def _env_secrets() -> list[str]:
    """Values of secret-named environment variables, longest first."""
    values = {
        value for name, value in os.environ.items()
        if _ENV_SECRET_NAME.search(name) and len(value.strip()) >= _MIN_ENV_SECRET_CHARS
    }
    return sorted(values, key=len, reverse=True)


def redact_text(text: str, env_secrets: list[str] | None = None) -> str:
    """Redact key-shaped strings and known secret values in a string."""
    text = _replace_registered(text)
    for secret in env_secrets if env_secrets is not None else _env_secrets():
        if secret in text:
            text = text.replace(secret, REDACTED)
    for pattern in _PATTERNS[:-1]:
        text = pattern.sub(REDACTED, text)
    return _HEADER_FORM.sub(lambda m: m.group(1) + m.group(2) + REDACTED, text)


def _walk(value, env_secrets: list[str]):
    """Redact a parsed JSON value: secret-named fields entirely, other strings by shape."""
    if isinstance(value, dict):
        return {
            key: REDACTED if is_secret_name(key) and not isinstance(val, (dict, list)) and val not in (None, "", 0)
            else _walk(val, env_secrets)
            for key, val in value.items()
        }
    if isinstance(value, list):
        return [_walk(item, env_secrets) for item in value]
    if isinstance(value, str):
        return redact_text(value, env_secrets)
    return value


def _redact_value(value, env_secrets: list[str]):
    """Redact an attribute value: JSON text is parsed so field names can be checked."""
    if isinstance(value, (list, tuple)):
        return [_redact_value(item, env_secrets) for item in value]
    if not isinstance(value, str):
        return value
    stripped = value.lstrip()
    if stripped[:1] in ("{", "[") and len(value) > 2:
        try:
            parsed = json.loads(value)
        except ValueError:
            parsed = None
        if isinstance(parsed, (dict, list)):
            return json.dumps(_walk(parsed, env_secrets), ensure_ascii=False)
    return redact_text(value, env_secrets)


def _redact_attributes(attributes: dict, env_secrets: list[str]) -> dict:
    result = {}
    for name, value in attributes.items():
        # An attribute whose own name is a secret field (e.g. "llm.api_key") is replaced whole.
        if is_secret_name(str(name).rsplit(".", 1)[-1]) and isinstance(value, str) and value:
            result[name] = REDACTED
        else:
            result[name] = _redact_value(value, env_secrets)
    return result


def redact_span(span: dict) -> dict:
    env_secrets = _env_secrets()
    if isinstance(span.get("name"), str):
        span["name"] = redact_text(span["name"], env_secrets)
    if isinstance(span.get("attributes"), dict):
        span["attributes"] = _redact_attributes(span["attributes"], env_secrets)
    for event in span.get("events") or []:
        if isinstance(event, dict):
            if isinstance(event.get("name"), str):
                event["name"] = redact_text(event["name"], env_secrets)
            if isinstance(event.get("attributes"), dict):
                event["attributes"] = _redact_attributes(event["attributes"], env_secrets)
    for link in span.get("links") or []:
        if isinstance(link, dict) and isinstance(link.get("attributes"), dict):
            link["attributes"] = _redact_attributes(link["attributes"], env_secrets)
    status = span.get("status")
    if isinstance(status, dict) and isinstance(status.get("description"), str):
        status["description"] = redact_text(status["description"], env_secrets)
    return span


def mask(span: dict) -> dict | None:
    """neatlogs mask: redact secrets, then screenshots. Never raises; on failure it falls
    back to redacting every string by shape, and drops the span if even that fails."""
    try:
        return trace_media.mask(redact_span(span))
    except Exception:
        try:
            return json.loads(redact_text(json.dumps(span, default=str)))
        except Exception:
            return None


def _active_span():
    """The active neatlogs span. In neatlogs' isolated mode it is not OpenTelemetry's current
    span, so neatlogs' own resolver is tried first (it is private API, hence the fallback)."""
    from opentelemetry import trace as otel_trace

    try:
        from neatlogs._wrap_utils import active_neatlogs_context

        context = active_neatlogs_context()
        if context is not None:
            return otel_trace.get_current_span(context)
    except Exception:
        pass
    return otel_trace.get_current_span()


def set_input(**values) -> bool:
    """Record the active span's input explicitly, as plain values.

    For traced functions that take objects (a run context, a page, a client) and so use
    capture_input=False: neatlogs walks an object's attributes when it captures arguments.
    Returns False when there is no active recording span.
    """
    span = _active_span()
    if span is None or not span.is_recording():
        return False
    span.set_attribute("input.value", json.dumps(values, default=str, ensure_ascii=False))
    span.set_attribute("input.mime_type", "application/json")
    return True
